Mesh<Point, double> mesh;
for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    if (is_small_edge(rt, *it, threshold)) {
        continue;
    }
    RT::Edge const &e = *it;
    RT::Cell_handle c1 = e.first;
    RT::Cell_handle c2 = e.second;
    for (auto cell : {c1, c2}) {
        std::vector<Point> polygon;
        RT::Cell_handle current_cell = cell;
        RT::Edge current_edge = e;
        do {
            polygon.push_back(rt.dual(current_edge));
            RT::Edge next_edge = rt.next_around_dual_face(current_edge, current_cell);
            current_edge = next_edge;
        } while (current_edge != e);
        mesh.add_face(polygon);
    }
}
return mesh;

